    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint v1, uint v2) public {
        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        uint mid = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(v2); if (__ESBMC_reverted()) return;
        uint fin = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(mid == v1 && fin == v2);
    }
}

